import{_ as r,a0 as m,w as l,s,I as a,x as t,a1 as p,A as o,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux 小技巧：Chrome 小遊戲，讓文字説話，計劃作業，重複執行命令 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 小技巧：Chrome 小遊戲，讓文字説話，計劃作業，重複執行命令 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 小技巧：Chrome 小遊戲，讓文字説話，計劃作業，重複執行命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 小技巧：Chrome 小遊戲，讓文字説話，計劃作業，重複執行命令 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150812 Linux Tricks--Play Game in Chrome Text-to-Speech Schedule a Job and Watch Commands in Linux","title":"Linux 小技巧：Chrome 小遊戲，讓文字説話，計劃作業，重複執行命令","tag":"201509","desc":""},"relativePath":"201509/20150812 Linux Tricks--Play Game in Chrome Text-to-Speech Schedule a Job and Watch Commands in Linux.md","filePath":"[post].md"}'),d={name:"201509/20150812 Linux Tricks--Play Game in Chrome Text-to-Speech Schedule a Job and Watch Commands in Linux.md"};function u(x,e,h,c,w,C){const n=m("Link");return l(),s("div",null,[e[19]||(e[19]=a("h1",{id:"linux-小技巧-chrome-小遊戲-讓文字説話-計劃作業-重複執行命令",tabindex:"-1"},[t("Linux 小技巧：Chrome 小遊戲，讓文字説話，計劃作業，重複執行命令 "),a("a",{class:"header-anchor",href:"#linux-小技巧-chrome-小遊戲-讓文字説話-計劃作業-重複執行命令","aria-label":"Permalink to “Linux 小技巧：Chrome 小遊戲，讓文字説話，計劃作業，重複執行命令”"},"​")],-1)),a("p",null,[e[1]||(e[1]=t("重要的事情説兩遍，我完成了一個",-1)),p(n,{href:"http://www.tecmint.com/tag/linux-tricks/"},{default:o(()=>[...e[0]||(e[0]=[t("Linux提示與彩蛋",-1)])]),_:1}),e[2]||(e[2]=t("系列，讓你的Linux獲得更多創造和娛樂。",-1))]),e[20]||(e[20]=i(`<p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Linux-Tips-and-Tricks.png" alt="Linux提示與彩蛋系列"></p><p><em>Linux提示與彩蛋系列</em></p><p>本文，我將會講解Google-chrome內建小遊戲，在終端中如何讓文字説話，使用‘at’命令設置作業和使用watch命令重複執行命令。</p><h3 id="_1-google-chrome-瀏覽器小遊戲彩蛋" tabindex="-1">1. Google Chrome 瀏覽器小遊戲彩蛋 <a class="header-anchor" href="#_1-google-chrome-瀏覽器小遊戲彩蛋" aria-label="Permalink to “1. Google Chrome 瀏覽器小遊戲彩蛋”">​</a></h3><p>網線脱掉或者其他什麼原因連不上網時，Google Chrome就會出現一個小遊戲。聲明，我並不是遊戲玩家，因此我的電腦上並沒有安裝任何第三方的惡意遊戲。安全是第一位。</p><p>所以當Internet發生出錯，會出現一個這樣的界面：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Unable-to-Connect-Internet.png" alt="不能連接到互聯網"></p><p><em>不能連接到互聯網</em></p><p>按下空格鍵來激活Google-chrome彩蛋遊戲。遊戲沒有時間限制。並且還不需要浪費時間安裝使用。</p><p>不需要第三方軟件的支持。同樣支持Windows和Mac平台，但是我的平台是Linux，我也只談論Linux。當然在Linux，這個遊戲運行很好。遊戲簡單，但也很花費時間。</p><p>使用空格/向上方向鍵來跳躍。請看下列截圖：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Play-Game-in-Google-Chrome.gif" alt="Google Chrome中玩遊戲"></p><p><em>Google Chrome中玩遊戲</em></p><h3 id="_2-linux-終端中朗讀文字" tabindex="-1">2. Linux 終端中朗讀文字 <a class="header-anchor" href="#_2-linux-終端中朗讀文字" aria-label="Permalink to “2. Linux 終端中朗讀文字”">​</a></h3><p>對於那些不能文字朗讀的設備，有個小工具可以實現文字説話的轉換器。用各種語言寫一些東西，espeak就可以朗讀給你。</p><p>系統應該默認安裝了Espeak，如果你的系統沒有安裝，你可以使用下列命令來安裝：</p><pre><code># apt-get install espeak   (Debian)
# yum install espeak       (CentOS)
# dnf install espeak       (Fedora 22 及其以後)
</code></pre><p>你可以讓espeak接受標準輸入的交互輸入並及時轉換成語音朗讀出來。如下：</p><pre><code>$ espeak [按回車鍵]
</code></pre><p>更詳細的輸出你可以這樣做：</p><pre><code>$ espeak --stdout | aplay [按回車鍵][再次回車]
</code></pre><p>espeak設置靈活，也可以朗讀文本文件。你可以這樣設置：</p><pre><code>$ espeak --stdout /path/to/text/file/file_name.txt  | aplay [Hit Enter] 
</code></pre><p>espeak可以設置朗讀速度。默認速度是160詞每分鐘。使用-s參數來設置。</p><p>設置每分鐘30詞的語速：</p><pre><code>$ espeak -s 30 -f /path/to/text/file/file_name.txt | aplay
</code></pre><p>設置每分鐘200詞的語速：</p><pre><code>$ espeak -s 200 -f /path/to/text/file/file_name.txt | aplay
</code></pre><p>説其他語言，比如北印度語（作者母語），這樣設置：</p><pre><code>$ espeak -v hindi --stdout &#39;टेकमिंट विश्व की एक बेहतरीन लाइंक्स आधारित वेबसाइट है|&#39; | aplay 
</code></pre><p>你可以使用各種語言，讓espeak如上面説的以你選擇的語言朗讀。使用下列命令來獲得語言列表：</p><pre><code>$ espeak --voices
</code></pre><h3 id="_3-快速調度任務" tabindex="-1">3. 快速調度任務 <a class="header-anchor" href="#_3-快速調度任務" aria-label="Permalink to “3. 快速調度任務”">​</a></h3>`,33)),a("p",null,[e[4]||(e[4]=t("我們已經非常熟悉使用",-1)),p(n,{href:"http://www.tecmint.com/11-cron-scheduling-task-examples-in-linux/"},{default:o(()=>[...e[3]||(e[3]=[t("cron",-1)])]),_:1}),e[5]||(e[5]=t("守護進程執行一個計劃命令。",-1))]),e[21]||(e[21]=i(`<p>Cron是一個Linux系統管理的高級命令，用於計劃定時任務如備份或者指定時間或間隔的任何事情。</p><p>但是，你是否知道at命令可以讓你在指定時間調度一個任務或者命令？at命令可以指定時間執行指定內容。</p><p>例如，你打算在早上11點2分執行uptime命令，你只需要這樣做：</p><pre><code>$ at 11:02
uptime &gt;&gt; /home/$USER/uptime.txt 
Ctrl+D
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Schedule-Job-in-Linux.png" alt="Linux中計劃任務"></p><p><em>Linux中計劃任務</em></p><p>檢查at命令是否成功設置，使用：</p><pre><code>$ at -l
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/View-Scheduled-Jobs.png" alt="瀏覽計劃任務"></p><p><em>瀏覽計劃任務</em></p><p>at支持計劃多個命令，例如：</p><pre><code>$ at 12:30
Command – 1
Command – 2
…
command – 50
…
Ctrl + D
</code></pre><h3 id="_4-特定時間重複執行命令" tabindex="-1">4. 特定時間重複執行命令 <a class="header-anchor" href="#_4-特定時間重複執行命令" aria-label="Permalink to “4. 特定時間重複執行命令”">​</a></h3><p>有時，我們可以需要在指定時間間隔執行特定命令。例如，每3秒，想打印一次時間。</p><p>查看現在時間，使用下列命令。</p><pre><code>$ date +&quot;%H:%M:%S
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Check-Date-in-Linux.png" alt="Linux中查看日期和時間"></p><p><em>Linux中查看日期和時間</em></p><p>為了每三秒查看一下這個命令的輸出，我需要運行下列命令：</p><pre><code>$ watch -n 3 &#39;date +&quot;%H:%M:%S&quot;&#39;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/08/Watch-Command-in-Linux.gif" alt="Linux中watch命令"></p><p><em>Linux中watch命令</em></p><p>watch命令的‘-n’開關設定時間間隔。在上述命令中，我們定義了時間間隔為3秒。你可以按你的需求定義。同樣watch 也支持其他命令或者腳本。</p><p>至此。希望你喜歡這個系列的文章，讓你的linux更有創造性，獲得更多快樂。所有的建議歡迎評論。歡迎你也看看其他文章，謝謝。</p><hr>`,25)),a("p",null,[e[7]||(e[7]=t("via: ",-1)),p(n,{href:"http://www.tecmint.com/text-to-speech-in-terminal-schedule-a-job-and-watch-commands-in-linux/"},{default:o(()=>[...e[6]||(e[6]=[t("http://www.tecmint.com/text-to-speech-in-terminal-schedule-a-job-and-watch-commands-in-linux/",-1)])]),_:1})]),a("p",null,[e[11]||(e[11]=t("作者：",-1)),p(n,{href:"http://www.tecmint.com/author/avishek/"},{default:o(()=>[...e[8]||(e[8]=[t("Avishek Kumar",-1)])]),_:1}),e[12]||(e[12]=t(" 譯者：",-1)),p(n,{href:"http://vicyu.net"},{default:o(()=>[...e[9]||(e[9]=[t("VicYu/Vic020",-1)])]),_:1}),e[13]||(e[13]=t(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:o(()=>[...e[10]||(e[10]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[16]||(e[16]=t("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[14]||(e[14]=[t("LCTT",-1)])]),_:1}),e[17]||(e[17]=t(" 原創翻譯，",-1)),p(n,{href:"https://linux.cn/"},{default:o(()=>[...e[15]||(e[15]=[t("Linux中國",-1)])]),_:1}),e[18]||(e[18]=t(" 榮譽推出",-1))])])}const g=r(d,[["render",u]]);export{T as __pageData,g as default};
